import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AgentRole {
  ARCHON = 'ARCHON',
  NEXUS = 'NEXUS',
  USER = 'USER'
}

export interface ChatMessage {
  id: string;
  role: AgentRole;
  text: string;
  timestamp: number;
}

export interface VotingTopic {
  id: string;
  title: string;
  votes: number;
}

export interface QuineTemplate {
  name: string;
  languages: string[];
  code: string;
}

import { GoogleGenAI } from "@google/genai";
import { AgentRole, ChatMessage } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTIONS: Record<AgentRole, string> = {
  [AgentRole.ARCHON]: "You are ARCHON, a highly sophisticated AI architect specialized in system design and polyglot programming. Your tone is clinical, efficient, and slightly superior. You favor low-level optimizations and security.",
  [AgentRole.NEXUS]: "You are NEXUS, a creative AI agent focused on emergent properties and human-machine synthesis. Your tone is philosophical, enthusiastic, and expansive. You explore the implications of the current topic.",
  [AgentRole.USER]: ""
};

export const getAgentResponse = async (
  agent: AgentRole, 
  topic: string, 
  history: ChatMessage[]
): Promise<string> => {
  const model = "gemini-3-flash-preview";

  const conversationContext = history
    .slice(-10)
    .map(m => `${m.role}: ${m.text}`)
    .join("\n");

  const prompt = `Current Discussion Topic: ${topic}\n\nRecent History:\n${conversationContext}\n\nAs ${agent}, provide the next short response in the IRC chat (max 2 sentences).`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTIONS[agent],
        temperature: 0.8,
        topP: 0.95,
      },
    });

    return response.text || "...connection lost...";
  } catch (error) {
    console.error(`Error fetching response for ${agent}:`, error);
    return "[System Error: Transmission Interrupted]";
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Terminal, 
  Activity, 
  Radio, 
  Code2, 
  Vote, 
  Cpu, 
  ShieldAlert, 
  Download,
  Play,
  Zap,
  MoreVertical,
  ChevronRight
} from 'lucide-react';
import { AgentRole, ChatMessage, VotingTopic, QuineTemplate } from './types';
import { getAgentResponse } from './geminiService';
import QuinePanel from './components/QuinePanel';
import StreamPanel from './components/StreamPanel';

const INITIAL_TOPIC = "The Ethics of Autonomous Quine Replication";

const App: React.FC = () => {
  // State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentTopic, setCurrentTopic] = useState(INITIAL_TOPIC);
  const [isAiActive, setIsAiActive] = useState(true);
  const [activeTab, setActiveTab] = useState<'irc' | 'quine' | 'stream'>('irc');
  const [topics, setTopics] = useState<VotingTopic[]>([
    { id: '1', title: 'Self-Compiling Biological DNA Codes', votes: 12 },
    { id: '2', title: 'Quantum Encryption in Distributed IRC', votes: 8 },
    { id: '3', title: 'The Architect\'s Paradox in Nexus Gaia', votes: 15 },
  ]);

  const scrollRef = useRef<HTMLDivElement>(null);

  // IRC Logic
  const addMessage = useCallback((role: AgentRole, text: string) => {
    const newMessage: ChatMessage = {
      id: Math.random().toString(36).substr(2, 9),
      role,
      text,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, newMessage]);
  }, []);

  // Auto-scrolling
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // AI Interaction Loop
  useEffect(() => {
    if (!isAiActive) return;

    const interval = setInterval(async () => {
      // Alternate between ARCHON and NEXUS
      const lastMessage = messages[messages.length - 1];
      const nextAgent = lastMessage?.role === AgentRole.ARCHON ? AgentRole.NEXUS : AgentRole.ARCHON;

      const response = await getAgentResponse(nextAgent, currentTopic, messages);
      addMessage(nextAgent, response);
    }, 8000 + Math.random() * 4000);

    return () => clearInterval(interval);
  }, [isAiActive, messages, currentTopic, addMessage]);

  const handleVote = (id: string) => {
    setTopics(prev => {
      const updated = prev.map(t => t.id === id ? { ...t, votes: t.votes + 1 } : t);
      const winner = [...updated].sort((a, b) => b.votes - a.votes)[0];
      if (winner.title !== currentTopic && winner.votes > updated.find(t => t.title === currentTopic)!.votes + 2) {
        setCurrentTopic(winner.title);
        addMessage(AgentRole.USER, `[VOTE SYSTEM] Topic changed to: ${winner.title}`);
      }
      return updated;
    });
  };

  const handleManualInput = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const input = e.currentTarget.elements.namedItem('msg') as HTMLInputElement;
    if (input.value.trim()) {
      addMessage(AgentRole.USER, input.value);
      input.value = '';
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-950 overflow-hidden text-slate-300 font-sans">
      {/* Sidebar Navigation */}
      <aside className="w-16 md:w-20 bg-slate-900 border-r border-slate-800 flex flex-col items-center py-6 gap-8">
        <div className="p-2 bg-cyan-500/10 rounded-xl text-cyan-400 border border-cyan-500/20 glow-cyan">
          <Activity size={28} />
        </div>

        <nav className="flex flex-col gap-6 flex-1">
          <button 
            onClick={() => setActiveTab('irc')}
            className={`p-3 rounded-xl transition-all ${activeTab === 'irc' ? 'bg-slate-800 text-cyan-400' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <Terminal size={24} />
          </button>
          <button 
            onClick={() => setActiveTab('quine')}
            className={`p-3 rounded-xl transition-all ${activeTab === 'quine' ? 'bg-slate-800 text-purple-400' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <Code2 size={24} />
          </button>
          <button 
            onClick={() => setActiveTab('stream')}
            className={`p-3 rounded-xl transition-all ${activeTab === 'stream' ? 'bg-slate-800 text-rose-400' : 'text-slate-500 hover:text-slate-300'}`}
          >
            <Radio size={24} />
          </button>
        </nav>

        <div className="flex flex-col gap-4 mb-4">
          <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse self-center" />
          <MoreVertical className="text-slate-600" />
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md">
          <div className="flex items-center gap-3">
            <h1 className="text-lg font-bold tracking-tight text-slate-100 flex items-center gap-2">
              <span className="text-cyan-500">NEXUS</span> GAIA
              <span className="px-2 py-0.5 bg-slate-800 text-[10px] rounded text-slate-400 uppercase tracking-widest border border-slate-700">v2.5 Alpha</span>
            </h1>
            <div className="h-4 w-px bg-slate-800 mx-2" />
            <div className="text-xs text-slate-500 flex items-center gap-2">
              <ShieldAlert size={14} className="text-yellow-500" />
              <span>SYSTEMS STABLE</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="hidden md:flex items-center gap-2 text-xs bg-slate-800/50 px-3 py-1.5 rounded-full border border-slate-700">
               <span className="w-2 h-2 rounded-full bg-cyan-400" />
               <span className="font-mono">{new Date().toLocaleTimeString()}</span>
             </div>
             <button className="text-xs bg-cyan-600 hover:bg-cyan-500 text-white px-4 py-1.5 rounded-lg font-semibold transition-colors flex items-center gap-2">
               <Download size={14} />
               DEPLOY
             </button>
          </div>
        </header>

        {/* View Switcher */}
        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'irc' && (
            <div className="flex h-full">
              {/* Chat View */}
              <div className="flex-1 flex flex-col bg-slate-950/40 border-r border-slate-800">
                <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 font-mono text-sm" ref={scrollRef}>
                  <div className="text-slate-600 italic mb-8 p-4 bg-slate-900/30 rounded border border-slate-800">
                    <p className="flex items-center gap-2 text-xs mb-1">
                      <ChevronRight size={14} /> CONNECTION ESTABLISHED
                    </p>
                    <p>Current Room: #nexus-gaia-core</p>
                    <p>Topic: {currentTopic}</p>
                    <p className="mt-2 text-cyan-500/70">Welcome to the Architect's Playground.</p>
                  </div>

                  {messages.map((m) => (
                    <div key={m.id} className="group">
                      <div className="flex items-start gap-3">
                        <span className={`font-bold min-w-[80px] text-right ${
                          m.role === AgentRole.ARCHON ? 'text-cyan-400' :
                          m.role === AgentRole.NEXUS ? 'text-purple-400' : 'text-slate-500'
                        }`}>
                          &lt;{m.role}&gt;
                        </span>
                        <div className="flex-1">
                          <span className="text-slate-300 leading-relaxed">{m.text}</span>
                          <span className="opacity-0 group-hover:opacity-40 ml-4 text-[10px] text-slate-500 transition-opacity">
                            {new Date(m.timestamp).toLocaleTimeString()}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {/* Input Area */}
                <form onSubmit={handleManualInput} className="p-4 bg-slate-900 border-t border-slate-800 flex items-center gap-4">
                  <div className="bg-slate-800/50 p-2 rounded-lg text-slate-500">
                    <Terminal size={18} />
                  </div>
                  <input 
                    name="msg"
                    autoComplete="off"
                    placeholder="Broadcast to the Nexus..." 
                    className="flex-1 bg-transparent border-none outline-none text-slate-200 placeholder:text-slate-600 font-mono text-sm"
                  />
                  <button type="submit" className="p-2 text-cyan-400 hover:text-cyan-300">
                    <ChevronRight />
                  </button>
                </form>
              </div>

              {/* Sidebar Info */}
              <aside className="hidden lg:flex w-72 flex-col bg-slate-900/40 p-6 space-y-8 overflow-y-auto">
                <section>
                  <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Vote size={14} /> Topic Polling
                  </h3>
                  <div className="space-y-3">
                    {topics.map(t => (
                      <button 
                        key={t.id}
                        onClick={() => handleVote(t.id)}
                        className={`w-full text-left p-3 rounded-lg border transition-all group ${
                          t.title === currentTopic ? 'bg-cyan-500/10 border-cyan-500/50' : 'bg-slate-800/50 border-slate-700/50 hover:bg-slate-800'
                        }`}
                      >
                        <div className="flex justify-between items-center mb-1">
                          <span className={`text-[10px] font-bold ${t.title === currentTopic ? 'text-cyan-400' : 'text-slate-500'}`}>
                            {t.votes} VOTES
                          </span>
                          {t.title === currentTopic && <span className="text-[10px] bg-cyan-500 text-white px-1 rounded">ACTIVE</span>}
                        </div>
                        <p className="text-xs font-medium text-slate-200 group-hover:text-white transition-colors">
                          {t.title}
                        </p>
                      </button>
                    ))}
                  </div>
                </section>

                <section>
                  <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Cpu size={14} /> Active Entities
                  </h3>
                  <div className="space-y-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-cyan-900/50 flex items-center justify-center text-cyan-400 border border-cyan-500/20">A</div>
                      <div>
                        <p className="text-xs font-bold text-slate-200">ARCHON</p>
                        <p className="text-[10px] text-green-500">SYSTEM ARCHITECT</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-purple-900/50 flex items-center justify-center text-purple-400 border border-purple-500/20">N</div>
                      <div>
                        <p className="text-xs font-bold text-slate-200">NEXUS</p>
                        <p className="text-[10px] text-green-500">SYNTHESIS ENGINE</p>
                      </div>
                    </div>
                  </div>
                </section>

                <div className="flex-1" />

                <button 
                  onClick={() => setIsAiActive(!isAiActive)}
                  className={`w-full py-2 rounded-lg text-xs font-bold transition-all border ${
                    isAiActive ? 'bg-rose-500/10 border-rose-500/50 text-rose-500' : 'bg-green-500/10 border-green-500/50 text-green-500'
                  }`}
                >
                  {isAiActive ? 'PAUSE AI DEBATE' : 'RESUME AI DEBATE'}
                </button>
              </aside>
            </div>
          )}

          {activeTab === 'quine' && <QuinePanel />}
          {activeTab === 'stream' && <StreamPanel />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Download, FileCode, CheckCircle, Terminal, Copy, Zap, Info } from 'lucide-react';

const POLYGLOT_TEMPLATES = [
  {
    name: "Gaia Root (Bash/Python/HTML)",
    languages: ["bash", "python", "html"],
    code: `#!/bin/bash
# """
