const QuinePanel: React.FC = () => {
  const [selected, setSelected] = useState(0);
  const [status, setStatus] = useState<string | null>(null);

  const handleDownload = () => {
    const blob = new Blob([POLYGLOT_TEMPLATES[selected].code], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nexus_quine_${selected}.poly`;
    a.click();
    URL.revokeObjectURL(url);
    setStatus("SAVED TO DISK");
    setTimeout(() => setStatus(null), 3000);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(POLYGLOT_TEMPLATES[selected].code);
    setStatus("COPIED TO BUFFER");
    setTimeout(() => setStatus(null), 3000);
  };

  return (
    <div className="h-full flex flex-col md:flex-row bg-slate-950 p-6 gap-6 overflow-y-auto">
      <div className="w-full md:w-80 space-y-4">
        <h2 className="text-xl font-bold text-slate-100 flex items-center gap-2 mb-6">
          <Terminal className="text-purple-500" />
          Quine Repository
        </h2>

        {POLYGLOT_TEMPLATES.map((t, idx) => (
          <button
            key={idx}
            onClick={() => setSelected(idx)}
            className={`w-full text-left p-4 rounded-xl border transition-all ${
              selected === idx ? 'bg-purple-500/10 border-purple-500/50' : 'bg-slate-900 border-slate-800 hover:border-slate-700'
            }`}
          >
            <p className="font-bold text-slate-200 text-sm mb-2">{t.name}</p>
            <div className="flex gap-2">
              {t.languages.map(l => (
                <span key={l} className="px-1.5 py-0.5 bg-slate-800 rounded text-[9px] uppercase font-mono text-slate-400">
                  {l}
                </span>
              ))}
            </div>
          </button>
        ))}

        <div className="p-4 bg-slate-900/50 rounded-xl border border-slate-800/50 mt-8">
            <h3 className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 mb-2">
                <Info size={14} /> Implementation Notes
            </h3>
            <p className="text-[11px] text-slate-400 leading-relaxed">
                Polyglot quines leverage divergent parser behaviors to execute as valid source in multiple runtimes. 
                Select a template to view the underlying logic flow.
            </p>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden shadow-2xl">
        <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
          <div className="flex items-center gap-3">
            <FileCode className="text-purple-400" size={20} />
            <span className="font-mono text-sm text-slate-300">source_viewer.exe --inspect</span>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={handleCopy}
              className="p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-slate-300 transition-colors"
              title="Copy to Clipboard"
            >
              <Copy size={16} />
            </button>
            <button 
              onClick={handleDownload}
              className="p-2 bg-purple-600 hover:bg-purple-500 rounded-lg text-white transition-colors flex items-center gap-2 text-xs font-bold"
            >
              <Download size={16} />
              PERSIST
            </button>
          </div>
        </div>

        <div className="flex-1 relative font-mono text-xs overflow-auto bg-slate-950 p-6 leading-relaxed text-slate-400 group">
          {status && (
            <div className="absolute top-4 right-4 bg-green-500 text-white px-3 py-1 rounded text-[10px] font-bold animate-bounce shadow-lg">
              {status}
            </div>
          )}
          <pre className="whitespace-pre-wrap selection:bg-purple-500/30">
            {POLYGLOT_TEMPLATES[selected].code}
          </pre>
        </div>

        <div className="p-4 bg-slate-900 border-t border-slate-800 flex justify-between items-center">
            <div className="flex items-center gap-6">
                 <div className="flex items-center gap-2">
                    <Zap size={14} className="text-yellow-500" />
                    <span className="text-[10px] text-slate-500">AUTONOMOUS MODE: ENABLED</span>
                 </div>
                 <div className="flex items-center gap-2">
                    <CheckCircle size={14} className="text-green-500" />
                    <span className="text-[10px] text-slate-500">HASH: SHA256 VALID</span>
                 </div>
            </div>
            <button className="flex items-center gap-2 text-[10px] font-bold text-slate-400 hover:text-white transition-colors">
                <Play size={14} /> SIMULATE EXECUTION
            </button>
        </div>
      </div>
    </div>
  );
};

export default QuinePanel;

import React, { useState, useEffect, useRef } from 'react';
import { Camera, Mic, Volume2, Settings, Users, Share2, Circle, Radio, ShieldCheck } from 'lucide-react';

const StreamPanel: React.FC = () => {
  const [isLive, setIsLive] = useState(false);
  const [viewers, setViewers] = useState(142);
  const [uptime, setUptime] = useState(0);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    let interval: any;
    if (isLive) {
      interval = setInterval(() => {
        setUptime(prev => prev + 1);
        setViewers(prev => prev + Math.floor(Math.random() * 5) - 2);
      }, 1000);
    } else {
      setUptime(0);
    }
    return () => clearInterval(interval);
  }, [isLive]);

  const toggleLive = async () => {
    if (!isLive) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
        setIsLive(true);
      } catch (err) {
        alert("Camera/Mic access required for Gaia stream.");
      }
    } else {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsLive(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="h-full bg-slate-950 p-6 flex flex-col gap-6 overflow-y-auto">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1">
        {/* Main Stream Container */}
        <div className="lg:col-span-2 flex flex-col gap-4">
          <div className="relative aspect-video bg-slate-900 rounded-2xl overflow-hidden border border-slate-800 shadow-2xl flex items-center justify-center">
            {isLive ? (
              <video 
                ref={videoRef} 
                autoPlay 
                muted 
                className="w-full h-full object-cover scale-x-[-1]"
              />
            ) : (
              <div className="text-center">
                <Radio size={64} className="text-slate-800 mb-4 mx-auto" />
                <p className="text-slate-600 font-mono">SIGNAL OFFLINE</p>
              </div>
            )}

            {/* HUD Overlay */}
            <div className="absolute top-4 left-4 flex gap-2">
              {isLive && (
                <div className="bg-red-600 text-white px-3 py-1 rounded text-[10px] font-bold flex items-center gap-2 animate-pulse">
                  <Circle size={8} fill="currentColor" /> LIVE
                </div>
              )}
              <div className="bg-black/60 backdrop-blur-md text-white px-3 py-1 rounded text-[10px] font-mono border border-white/10">
                {isLive ? formatTime(uptime) : '00:00'}
              </div>
            </div>

            <div className="absolute bottom-4 right-4 flex gap-2">
                <div className="bg-black/60 backdrop-blur-md text-cyan-400 px-3 py-1 rounded text-[10px] font-mono border border-cyan-400/20 flex items-center gap-2">
                    <Users size={12} /> {viewers}
                </div>
            </div>
          </div>

          <div className="flex items-center justify-between p-4 bg-slate-900 rounded-xl border border-slate-800">
            <div className="flex gap-4">
              <button className="p-2.5 bg-slate-800 hover:bg-slate-700 rounded-full text-slate-400">
                <Mic size={20} />
              </button>
              <button className="p-2.5 bg-slate-800 hover:bg-slate-700 rounded-full text-slate-400">
                <Camera size={20} />
              </button>
              <button className="p-2.5 bg-slate-800 hover:bg-slate-700 rounded-full text-slate-400">
                <Volume2 size={20} />
              </button>
            </div>

            <button 
              onClick={toggleLive}
              className={`px-8 py-2.5 rounded-full font-bold text-sm transition-all shadow-lg ${
                isLive 
